using He_Thong_GYM.Models;
using Microsoft.Data.SqlClient;
namespace He_Thong_GYM.DAL;
public sealed class HuanLuyenVienDAL
{
 public async Task<List<HuanLuyenVien>> LayDanhSachAsync(string? tuKhoa=null){const string sql="""SELECT h.MaHLV,h.MaNV,n.HoTen,h.ChuyenMon,h.KinhNghiem,h.PhiThue,n.TrangThai FROM dbo.HuanLuyenVien h JOIN dbo.NhanVien n ON n.MaNV=h.MaNV WHERE @TuKhoa IS NULL OR n.HoTen LIKE N'%'+@TuKhoa+N'%' OR h.ChuyenMon LIKE N'%'+@TuKhoa+N'%' ORDER BY h.MaHLV DESC;""";var kq=new List<HuanLuyenVien>();await using var cn=DbConnectionFactory.CreateConnection();await using var cmd=new SqlCommand(sql,cn);cmd.Parameters.Add("@TuKhoa",System.Data.SqlDbType.NVarChar,100).Value=string.IsNullOrWhiteSpace(tuKhoa)?DBNull.Value:tuKhoa.Trim();await cn.OpenAsync();await using var rd=await cmd.ExecuteReaderAsync();while(await rd.ReadAsync())kq.Add(new HuanLuyenVien{MaHLV=rd.GetInt32(0),MaNV=rd.GetInt32(1),HoTen=rd.GetString(2),ChuyenMon=rd.IsDBNull(3)?null:rd.GetString(3),KinhNghiem=rd.IsDBNull(4)?null:rd.GetInt32(4),PhiThue=rd.IsDBNull(5)?null:rd.GetDecimal(5),TrangThaiNhanVien=rd.GetString(6)});return kq;}
 public async Task<int> ThemAsync(HuanLuyenVien h){const string sql="INSERT dbo.HuanLuyenVien(MaNV,ChuyenMon,KinhNghiem,PhiThue) VALUES(@MaNV,@ChuyenMon,@KinhNghiem,@PhiThue);SELECT CAST(SCOPE_IDENTITY() AS int);";return await LuuAsync(sql,h,true);}
 public Task<int> CapNhatAsync(HuanLuyenVien h)=>LuuAsync("UPDATE dbo.HuanLuyenVien SET MaNV=@MaNV,ChuyenMon=@ChuyenMon,KinhNghiem=@KinhNghiem,PhiThue=@PhiThue WHERE MaHLV=@MaHLV;",h,false);
 private static async Task<int> LuuAsync(string sql,HuanLuyenVien h,bool identity){await using var cn=DbConnectionFactory.CreateConnection();await using var cmd=new SqlCommand(sql,cn);cmd.Parameters.Add("@MaHLV",System.Data.SqlDbType.Int).Value=h.MaHLV;cmd.Parameters.Add("@MaNV",System.Data.SqlDbType.Int).Value=h.MaNV;cmd.Parameters.Add("@ChuyenMon",System.Data.SqlDbType.NVarChar,255).Value=(object?)h.ChuyenMon??DBNull.Value;cmd.Parameters.Add("@KinhNghiem",System.Data.SqlDbType.Int).Value=(object?)h.KinhNghiem??DBNull.Value;cmd.Parameters.Add("@PhiThue",System.Data.SqlDbType.Decimal).Value=(object?)h.PhiThue??DBNull.Value;await cn.OpenAsync();return identity?(int)(await cmd.ExecuteScalarAsync()??throw new InvalidOperationException()):await cmd.ExecuteNonQueryAsync();}
}
